# Classic poems, Grades 2–12 (public domain; copied from Gutenberg editions).
from spec_a import P

# ---------------- Grades 2–4 ----------------
P('bedsummer', 'childsgarden', 'In winter I get up at night', 'To have to go to bed by day?', 'Bed in Summer', 'Robert Louis Stevenson', 1885, [
  ('What is the child’s problem in summer?', 'He has to go to bed while it is still light', ['He cannot sleep at all', 'He must get up in the dark', 'He is too hot to play'], '“In summer quite the other way, / I have to go to bed by day.”'),
  ('How is winter different from summer for the child?', 'In winter he gets up while it is still dark', ['In winter he never sleeps', 'In winter he plays outside all night', 'There is no difference'], '“In winter I get up at night / And dress by yellow candle-light.”'),
  ('What can the child still hear from his bed?', 'Grown-up people’s feet going past in the street', ['Rain on the roof', 'His friends calling him', 'Music from a party'], 'He hears “the grown-up people\'s feet / Still going past me in the street.”'),
  ('How does the child feel about going to bed early?', 'It seems unfair and hard', ['He is happy to rest', 'He is scared of the dark', 'He does not mind at all'], '“And does it not seem hard to you … To have to go to bed by day?”'),
], poem=True)
P('swing', 'childsgarden', 'How do you like to go up in a swing', 'Up in the air and down!', 'The Swing', 'Robert Louis Stevenson', 1885, [
  ('How does the child feel about swinging?', 'It is the pleasantest thing a child can do', ['It is scary', 'It is boring', 'It is only for babies'], '“Oh, I do think it the pleasantest thing / Ever a child can do!”'),
  ('What can the child see from high on the swing?', 'River, trees, cattle and the countryside', ['The ocean and ships', 'A big city', 'Only the sky'], '“River and trees and cattle and all / Over the countryside.”'),
  ('Why does the poet repeat “Up in the air”?', 'To copy the back-and-forth rhythm of swinging', ['Because he forgot the words', 'To show he is falling', 'To make the poem sad'], 'The repeated words rise and fall like a swing.'),
  ('Which word pairs rhyme in the poem?', 'swing / thing', ['swing / blue', 'air / wall', 'trees / brown'], '“Swing” and “thing” end with the same sound.'),
], poem=True)
P('wind', 'singsong', 'Who has seen the wind?', 'The wind is passing by.', 'Who Has Seen the Wind?', 'Christina Rossetti', 1872, [
  ('According to the poem, who has seen the wind?', 'Nobody — neither you nor I', ['Only the trees', 'Only the poet', 'Everyone'], '“Neither I nor you.”'),
  ('How can we tell the wind is there?', 'By what it does to leaves and trees', ['By its colour', 'By its smell', 'By its shadow'], '“When the leaves hang trembling / The wind is passing thro’.”'),
  ('What does “the trees bow down their heads” describe?', 'Trees bending in the wind', ['Trees being cut down', 'Trees saying thank you', 'Trees falling asleep'], 'Rossetti gives the trees a human action — personification.'),
  ('What is the big idea of the poem?', 'You can know something is real by its effects, even if you cannot see it', ['Wind is dangerous', 'Trees are alive', 'Leaves fall in autumn'], 'We never see the wind, but we see what it moves.'),
], poem=True, nth=2)
P('crocodile', 'alice', 'How doth the little crocodile', 'With gently smiling jaws!', 'How Doth the Little Crocodile (Alice’s Adventures in Wonderland)', 'Lewis Carroll', 1865, [
  ('What does the crocodile pour over his golden scales?', 'The waters of the Nile', ['Honey', 'Sand', 'Rain'], 'He pours “the waters of the Nile / On every golden scale!”'),
  ('Why is the crocodile “smiling”?', 'He is welcoming little fishes into his mouth to eat them', ['He is happy to see Alice', 'He told a joke', 'He is a friendly pet'], '“And welcome little fishes in / With gently smiling jaws!”'),
  ('What makes this poem funny?', 'It describes a dangerous crocodile in a sweet, gentle way', ['It has no rhymes', 'The crocodile cannot swim', 'It is about a cat'], '“Cheerfully,” “neatly” and “gently” make a hunter sound polite.'),
  ('Which words rhyme in the first verse?', 'tail / scale and Nile / crocodile', ['tail / Nile', 'crocodile / scale', 'grin / claws'], 'Lines 2 and 4 end “tail / scale”; lines 1 and 3 end “crocodile / Nile.”'),
], poem=True)
P('owl', 'lear', 'The Owl and the Pussy-Cat went to sea', 'With a ring at the end of his nose.', 'The Owl and the Pussy-Cat', 'Edward Lear', 1871, [
  ('How did the Owl and the Pussy-Cat travel?', 'In a beautiful pea-green boat', ['On a flying carpet', 'By train', 'On a big whale'], 'They “went to sea / In a beautiful pea-green boat.”'),
  ('What did they take with them?', 'Some honey and plenty of money', ['A map and a compass', 'Bread and cheese', 'A ring and a hat'], '“They took some honey, and plenty of money.”'),
  ('What problem did they have when they wanted to marry?', 'They had no ring', ['The boat was sinking', 'They had no money', 'The Owl could not sing'], '“But what shall we do for a ring?”'),
  ('Where did they find a ring?', 'On the nose of a Piggy-wig', ['At the bottom of the sea', 'In a shop', 'In the Owl’s pocket'], 'A Piggy-wig stood “With a ring at the end of his nose.”'),
  ('What kind of poem is this?', 'A nonsense poem', ['A sad war poem', 'A science report', 'A sonnet'], 'Lear invents silly words and impossible events, like a Bong-tree.'),
], poem=True)
P('eagle', 'tennyson', 'He clasps the crag with hooked hands', 'And like a thunderbolt he falls.', 'The Eagle', 'Alfred, Lord Tennyson', 1851, [
  ('Where is the eagle at the start of the poem?', 'High on a rocky cliff (crag)', ['In a nest in a tree', 'Flying over the sea', 'In a cage'], '“He clasps the crag with hooked hands.”'),
  ('The eagle has “hooked hands.” Why is this word choice interesting?', 'Calling claws “hands” makes the eagle seem almost human', ['Eagles really have hands', 'It shows the eagle is old', 'It is a spelling mistake'], 'This is personification.'),
  ('“The wrinkled sea beneath him crawls” suggests …', 'the eagle is so high the waves look like slow wrinkles', ['the sea is very old', 'the sea is calm and flat', 'the eagle is underwater'], 'From far above, big waves look tiny and slow.'),
  ('What does “like a thunderbolt he falls” describe?', 'The eagle diving suddenly and powerfully', ['The eagle being struck by lightning', 'A storm starting', 'The eagle falling asleep'], 'A simile: fast and powerful, like lightning.'),
], poem=True)

# ---------------- Grades 5–8 ----------------
P('jabberwocky', 'lookingglass', '’Twas brillig, and the slithy toves', 'He chortled in his joy.', 'Jabberwocky (Through the Looking-Glass)', 'Lewis Carroll', 1871, [
  ('What happens in the poem?', 'A young hero slays a monster called the Jabberwock', ['A boy loses his sword', 'A bird builds a nest', 'Two friends sail to sea'], '“The vorpal blade went snicker-snack! / He left it dead.”'),
  ('Many words, like “brillig” and “slithy,” are invented. How can readers still follow the story?', 'Grammar and context show what the words are doing', ['They are explained in a glossary in the poem', 'They are real words from Old English', 'They cannot follow it'], 'Even nonsense words sit in normal sentence patterns.'),
  ('“Snicker-snack” is an example of …', 'onomatopoeia', ['a simile', 'a metaphor', 'alliteration only'], 'It imitates the sound of the blade.'),
  ('How does the father feel at the end?', 'Overjoyed', ['Angry', 'Worried', 'Bored'], '“O frabjous day! Callooh! Callay!” He chortled in his joy.'),
  ('“Chortled” (a word Carroll invented) is probably a mix of …', 'chuckle and snort', ['chortle and turtle', 'chop and toll', 'cheer and startle'], 'Carroll blended words — “portmanteau” words — and “chortle” is now in the dictionary.'),
], poem=True)
P('daffodils', 'golden', "I wander'd lonely as a cloud", 'And dances with the daffodils.', 'I Wandered Lonely as a Cloud (Daffodils)', 'William Wordsworth', 1807, [
  ('What does the poet suddenly see?', 'A host of golden daffodils', ['A flock of birds', 'A rainbow over the lake', 'A crowd of people'], '“When all at once I saw a crowd, / A host of golden daffodils.”'),
  ('“I wander\'d lonely as a cloud” is an example of …', 'a simile', ['a metaphor', 'onomatopoeia', 'hyperbole'], 'It compares the poet to a cloud using “as.”'),
  ('How are the daffodils personified?', 'They dance and toss their heads', ['They cry and sleep', 'They shout and run', 'They read and write'], '“Tossing their heads in sprightly dance.”'),
  ('What is the “wealth” the daffodils brought him?', 'A happy memory he can enjoy later', ['Money from selling flowers', 'A new garden', 'Fame as a poet'], '“They flash upon that inward eye … And then my heart with pleasure fills.”'),
  ('What does the “inward eye” refer to?', 'His memory and imagination', ['His glasses', 'A camera', 'A dream at night'], 'He sees the daffodils again in his mind, “the bliss of solitude.”'),
], poem=True)
P('woods', 'frostnh', 'Whose woods these are I think I know.', 'And miles to go before I sleep.', 'Stopping by Woods on a Snowy Evening', 'Robert Frost', 1923, [
  ('Why does the speaker stop?', 'To watch the woods fill up with snow', ['His horse is hurt', 'He is lost', 'He is visiting a friend'], 'He stops “To watch his woods fill up with snow.”'),
  ('Why does the horse shake its harness bells?', 'It seems to wonder why they stopped where there is no farmhouse', ['It is cold', 'It hears a wolf', 'It wants to go faster'], '“To ask if there is some mistake.”'),
  ('Why does the speaker not stay?', 'He has promises to keep and a long way to go', ['It is too cold', 'The owner sees him', 'His horse runs off'], '“But I have promises to keep, / And miles to go before I sleep.”'),
  ('Why might Frost repeat the last line?', 'To suggest deeper meaning — life’s duties before the final rest', ['He ran out of words', 'To show he is lost', 'To make the poem longer'], 'The repeated line can mean both a night’s sleep and the end of life.'),
  ('What is the mood of the poem?', 'Quiet and thoughtful', ['Loud and exciting', 'Angry', 'Silly'], '“The only other sound’s the sweep / Of easy wind and downy flake.”'),
], poem=True)
P('nothinggold', 'frostnh', 'Nature’s first green is gold', 'Nothing gold can stay.', 'Nothing Gold Can Stay', 'Robert Frost', 1923, [
  ('What is the “gold” at the start of the poem?', 'The first golden-green buds of spring', ['Real gold coins', 'Autumn leaves', 'The sun'], '“Nature’s first green is gold, / Her hardest hue to hold.”'),
  ('What happens to the early leaf that is “a flower”?', 'It lasts only a short time', ['It lasts forever', 'It turns to stone', 'It is picked'], '“But only so an hour.”'),
  ('What is the theme of the poem?', 'Beautiful things, like youth and new beginnings, do not last', ['Gold is precious', 'Leaves are green', 'Nature never changes'], '“Nothing gold can stay.”'),
  ('“So dawn goes down to day” means …', 'the special beauty of dawn fades into an ordinary day', ['the sun sets in the morning', 'day turns into night', 'dawn is the best time to wake up'], 'Like the leaf and Eden, the golden moment passes.'),
], poem=True)
P('ocaptain', 'leaves', 'O Captain! my Captain! our fearful trip is done', 'Fallen cold and dead.', 'O Captain! My Captain!', 'Walt Whitman', 1865, [
  ('Who does the “Captain” stand for?', 'President Abraham Lincoln', ['A real sea captain', 'Whitman’s father', 'A soldier'], 'Whitman wrote it in 1865 after Lincoln was assassinated.'),
  ('What does the “fearful trip” that is “done” represent?', 'The American Civil War', ['A storm at sea', 'A long holiday', 'A race'], 'The ship has “weather’d every rack, the prize we sought is won.”'),
  ('Why is the mood a contrast between joy and grief?', 'The crowds celebrate victory while the speaker mourns his captain', ['Everyone is sad', 'Everyone is happy', 'The ship is sinking'], '“Exult O shores, and ring O bells! / But I with mournful tread.”'),
  ('The whole poem compares the nation to a ship. This is …', 'an extended metaphor', ['onomatopoeia', 'a simile', 'a pun'], 'Ship, voyage and captain stand for the country, the war and the President.'),
], poem=True, endnth=2)
P('if', 'kipling_rewards', 'If you can keep your head when all about you', 'you’ll be a Man, my son!', 'If—', 'Rudyard Kipling', 1910, [
  ('Who is the speaker addressing?', 'His son', ['A king', 'A crowd of soldiers', 'His teacher'], 'The poem ends, “you’ll be a Man, my son!”'),
  ('“Keep your head when all about you / Are losing theirs” means …', 'stay calm when others panic', ['wear a helmet', 'do not fall asleep', 'agree with everyone'], 'Losing your head means losing control.'),
  ('Why does Kipling call Triumph and Disaster “impostors”?', 'Neither success nor failure should change who you are', ['They are real people', 'They are tricks played by friends', 'They always lie'], 'Treat “those two impostors just the same.”'),
  ('What structure does the poem use?', 'A long series of “If” conditions leading to one conclusion', ['A conversation between two people', 'A list of instructions for a game', 'A story told in order'], 'Every condition builds toward “Yours is the Earth.”'),
  ('“Fill the unforgiving minute / With sixty seconds’ worth of distance run” means …', 'make every moment count', ['run a race in a minute', 'never waste time sleeping', 'always be early'], 'Time does not forgive waste, so use all of it.'),
], poem=True)
P('tyger', 'blake', 'Tiger, tiger, burning bright', 'Dare frame thy fearful symmetry?', 'The Tiger (Songs of Experience)', 'William Blake', 1794, [
  ('What question does the speaker keep asking?', 'What kind of creator could make such a fierce tiger', ['Where the tiger lives', 'What the tiger eats', 'How old the tiger is'], '“What immortal hand or eye / Could frame thy fearful symmetry?”'),
  ('Why does the speaker mention the lamb?', 'To wonder whether the same creator made both the gentle and the fierce', ['Because the tiger ate the lamb', 'Because lambs are also striped', 'To describe a farm'], '“Did He who made the lamb make thee?”'),
  ('“Burning bright” describes the tiger as …', 'fiery and dazzling, like a flame in the dark forest', ['actually on fire', 'very hot from the sun', 'sick with a fever'], 'Its eyes and stripes glow “In the forests of the night.”'),
  ('Why does “Could frame” become “Dare frame” in the last stanza?', 'The speaker is now awed that anyone would dare create something so terrible', ['It is a misprint', 'The tiger has changed', 'The poet forgot the first stanza'], 'One changed word turns ability (“could”) into daring.'),
  ('Which images compare the creator to a blacksmith?', 'The hammer, chain, furnace and anvil', ['The stars and spears', 'The forests and night', 'The lamb and the tiger'], '“What the hammer? what the chain? / In what furnace was thy brain?”'),
], poem=True)
P('raven', 'poe_raven', 'Once upon a midnight dreary', 'This it is, and nothing more.”', 'The Raven', 'Edgar Allan Poe', 1845, [
  ('What is the speaker doing at the start?', 'Reading old books late at night, nearly asleep', ['Walking in a storm', 'Writing a letter', 'Talking to a friend'], 'He was pondering “Over many a quaint and curious volume of forgotten lore.”'),
  ('Why is the speaker sad?', 'He is mourning the loss of Lenore', ['He lost his books', 'He is ill', 'His fire went out'], 'He sought “surcease of sorrow—sorrow for the lost Lenore.”'),
  ('“Nearly napping, suddenly there came a tapping” is an example of …', 'internal rhyme', ['a simile', 'free verse', 'understatement'], '“Napping” and “tapping” rhyme inside the line.'),
  ('Why does the speaker keep repeating that it is only a visitor?', 'To calm his own growing fear', ['He knows exactly who it is', 'He is expecting a friend', 'He wants the visitor to leave'], 'He repeats it “to still the beating of my heart.”'),
  ('What mood do “bleak December” and “dying ember” create?', 'Gloomy and eerie', ['Cheerful', 'Peaceful', 'Silly'], 'Cold, darkness and fading fire set a haunted mood.'),
], poem=True)

# ---------------- Grades 9–12 ----------------
P('ozymandias', 'golden', 'I met a traveller from an antique land', 'The lone and level sands stretch far away.', 'Ozymandias', 'Percy Bysshe Shelley', 1818, [
  ('What remains of Ozymandias’s statue?', 'Two legs of stone and a broken face half buried in sand', ['The whole statue, perfectly preserved', 'Only the pedestal', 'Nothing at all'], '“Two vast and trunkless legs of stone … Half sunk, a shatter\'d visage lies.”'),
  ('What is ironic about the words on the pedestal?', 'He boasts of mighty works, but nothing of them remains', ['The words are misspelled', 'They praise the sculptor', 'They warn travellers about the desert'], '“Look on my works, ye Mighty, and despair!” / Nothing beside remains.'),
  ('What does the sculptor’s work reveal about the king?', 'He was proud and cruel — the frown and “sneer of cold command”', ['He was kind and humble', 'He was a great artist', 'He was young and happy'], 'The sculptor “well those passions read.”'),
  ('What is the theme of the poem?', 'Power and pride do not last; time destroys all', ['Deserts are beautiful', 'Statues should be protected', 'Travel teaches us history'], '“The lone and level sands stretch far away.”'),
  ('What poetic form is “Ozymandias”?', 'A sonnet (14 lines)', ['A limerick', 'A haiku', 'A ballad'], 'It has fourteen lines in iambic pentameter.'),
], poem=True)
P('deathstop', 'dickinson', 'Because I could not stop for Death', 'Were toward eternity.', 'Because I Could Not Stop for Death', 'Emily Dickinson', 1890, [
  ('How is Death personified in the poem?', 'As a polite gentleman driving a carriage', ['As a frightening monster', 'As a thief at night', 'As a storm'], '“He kindly stopped for me … For his civility.”'),
  ('Who else rides in the carriage?', 'Immortality', ['The speaker’s family', 'A school class', 'No one'], '“The carriage held but just ourselves / And Immortality.”'),
  ('What might the school, the grain and the setting sun stand for?', 'The stages of life — childhood, maturity and old age', ['Places the speaker likes', 'A trip to the country', 'The seasons of farming'], 'The journey passes the whole course of a life.'),
  ('What is the “house” that “seemed / A swelling of the ground”?', 'A grave', ['A farmhouse', 'A church', 'A school'], '“The roof was scarcely visible, / The cornice but a mound.”'),
  ('What is the tone of the poem toward death?', 'Calm and accepting', ['Terrified', 'Angry', 'Joking'], 'Death is kind and the ride is slow; she feels no haste or fear.'),
], poem=True)
P('sonnet116', 'sonnets', 'Let me not to the marriage of true minds', 'nor no man ever lov’d.', 'Sonnet 116', 'William Shakespeare', 1609, [
  ('According to the sonnet, true love …', 'does not change when circumstances change', ['fades with time', 'needs to be tested often', 'is impossible'], '“Love is not love / Which alters when it alteration finds.”'),
  ('Love is called “an ever-fixed mark” and “the star to every wandering bark.” What do these suggest?', 'Love is steady and guides us like a lighthouse or the North Star', ['Love is hard to see', 'Love is far away', 'Love is like a shipwreck'], 'A bark is a ship; the star guides lost ships.'),
  ('“Love’s not Time’s fool” means …', 'love is not ruled by time, even as youth and beauty fade', ['love is foolish', 'love wastes time', 'time is foolish'], 'Rosy lips and cheeks fall to Time’s “bending sickle,” but love lasts.'),
  ('How does the final couplet support the poem’s claim?', 'If he is wrong, then no one has ever written or loved', ['It admits he is wrong', 'It changes the subject', 'It asks a question'], '“If this be error and upon me prov’d, / I never writ, nor no man ever lov’d.”'),
], poem=True)
P('worldtoomuch', 'golden', 'The World is too much with us; late and soon', 'wreathed horn.', 'The World Is Too Much with Us', 'William Wordsworth', 1807, [
  ('What does Wordsworth criticize?', 'People are too busy getting and spending to notice nature', ['People spend too much time outdoors', 'The world is too crowded', 'Pagans are wrong'], '“Getting and spending, we lay waste our powers; / Little we see in Nature that is ours.”'),
  ('“We have given our hearts away, a sordid boon!” means …', 'we traded our feelings for something cheap and shameful', ['we fell in love', 'we gave gifts to charity', 'we lost a contest'], 'A sordid boon is a worthless, ugly gift.'),
  ('Why would the speaker “rather be / A Pagan”?', 'Pagans at least felt wonder at nature', ['He dislikes his religion', 'Pagans were richer', 'He wants to live by the sea'], 'He wants “glimpses that would make me less forlorn.”'),
  ('“For this, for everything, we are out of tune” compares people to …', 'an instrument that no longer plays in harmony with nature', ['a song nobody likes', 'a broken clock', 'a quiet sea'], 'We no longer respond to the sea, the moon and the winds.'),
], poem=True)
P('redrose', 'golden', "O my Luve's like a red, red rose", "Tho' it were ten thousand mile.", 'A Red, Red Rose', 'Robert Burns', 1794, [
  ('To what two things does the speaker compare his love?', 'A red rose newly sprung in June, and a sweet melody', ['The sun and the moon', 'The sea and the sand', 'A star and a candle'], '“O my Luve\'s like a red, red rose … O my Luve\'s like the melodie.”'),
  ('How long will his love last?', 'Until the seas go dry and the rocks melt', ['Until June', 'Until they are married', 'For one year'], '“Till a\' the seas gang dry … And the rocks melt wi\' the sun.”'),
  ('“Till a\' the seas gang dry” is an example of …', 'hyperbole', ['understatement', 'onomatopoeia', 'irony'], 'The seas will never go dry — he exaggerates to show his love is endless.'),
  ('Why does the poem use spellings like “Luve” and “gang”?', 'Burns wrote in Scots dialect', ['They are spelling mistakes', 'They are invented words', 'They show the speaker is a child'], 'Burns was Scotland’s national poet.'),
], poem=True)
P('annabel', 'poe_raven', 'It was many and many a year ago', 'Coveted her and me.', 'Annabel Lee', 'Edgar Allan Poe', 1849, [
  ('Where does the story of the poem take place?', 'In a kingdom by the sea', ['In a dark forest', 'In a castle in the mountains', 'In a big city'], '“In a kingdom by the sea.”'),
  ('How old were the speaker and Annabel Lee when they loved?', 'They were both children', ['They were old', 'He was a king and she a queen', 'The poem does not say'], '“I was a child and She was a child.”'),
  ('What does it mean that the angels “coveted” their love?', 'The angels were jealous of it', ['The angels protected it', 'The angels did not notice', 'The angels sang about it'], 'To covet is to want what someone else has.'),
  ('What is the effect of repeating “In this kingdom by the sea”?', 'It creates a musical, dreamlike, fairy-tale feeling', ['It shows he forgot the line', 'It makes the poem funny', 'It gives directions'], 'Poe uses repetition like a song’s refrain.'),
], poem=True)
P('mask', 'dunbar', 'We wear the mask that grins and lies,', 'We wear the mask!', 'We Wear the Mask', 'Paul Laurence Dunbar', 1896, [
  ('What does the “mask” hide?', 'Pain and suffering behind a smiling face', ['A real face covering', 'A crime', 'A joke'], '“With torn and bleeding hearts we smile.”'),
  ('Why does the speaker say the world should not be “over-wise”?', 'The world does not need to see all their tears and sighs', ['The world is already too clever', 'People should study less', 'Masks are illegal'], '“In counting all our tears and sighs? / Nay, let them only see us, while / We wear the mask.”'),
  ('Dunbar was the son of formerly enslaved parents. Whose experience does “we” most likely speak for?', 'African Americans facing racism and hardship', ['Actors in a theatre', 'Children at a party', 'Soldiers in a war'], 'The mask is the smile they had to show a hostile world.'),
  ('What is the tone of the last stanza?', 'Anguished but defiant', ['Cheerful', 'Indifferent', 'Comic'], '“Our cries / To thee from tortured souls arise … We wear the mask!”'),
], poem=True)
